const paths={home:'M3 11 12 3l9 8M5 10v11h5v-7h4v7h5V10',closet:'M10 5a2 2 0 1 1 3 2v2l8 7a2 2 0 0 1-1 3H4a2 2 0 0 1-1-3l9-7M12 9v10',plus:'M12 5v14M5 12h14',outfits:'m8 4 4 2 4-2 5 4-3 4-2-1v10H8V11l-2 1-3-4 5-4ZM9 16h6',profile:'M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2H4Z',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',heart:'M20 4c-3-2-6 0-8 2-2-2-5-4-8-2-6 5 2 12 8 16 6-4 14-11 8-16Z',grid:'M3 3h7v7H3V3Zm11 0h7v7h-7V3ZM3 14h7v7H3v-7Zm11 0h7v7h-7v-7Z',layers:'m12 2 10 5-10 5L2 7l10-5ZM2 12l10 5 10-5M2 17l10 5 10-5',calendar:'M4 5h16v16H4V5ZM7 2v6m10-6v6M4 10h16m4 4h2m3 0h2m-7 4h2',bag:'M5 5h14v17H5V5ZM9 5V2h6v3M9 9v9m6-9v9',chart:'M4 13h3v8H4v-8Zm7-7h3v15h-3V6Zm7-4h3v19h-3V2Z',camera:'M3 7h4l2-3h6l2 3h4v14H3V7Zm13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',cube:'m12 2 10 5v10l-10 5-10-5V7l10-5ZM2 7l10 5 10-5M12 12v10M7 4.5l10 5v5',sparkle:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z',sliders:'M3 6h5m4 0h9M3 12h10m4 0h4M3 18h2m4 0h12M8 3v6m5 0v6M5 15v6',more:'M4 12h.01M12 12h.01M20 12h.01',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',upload:'M12 16V2m-5 5 5-5 5 5M3 14v8h18v-8',image:'M3 3h18v18H3V3Zm0 14 6-6 4 4 3-3 5 5M8 7h.01',rotate:'M21 7v5h-5M3 17v-5h5M4 8a8 8 0 0 1 14-4l3 3M3 17l3 3a8 8 0 0 0 14-4',settings:'M9 3h6l1 3 3 1 2 5-2 2v4l-5 3-3-2-3 1-4-4 1-3-2-3 3-5h3l1-2Zm7 9a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',cloud:'M6 18a5 5 0 0 1-1-10 7 7 0 0 1 13-1 5.5 5.5 0 0 1 0 11H6Z',help:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM9 8a3 3 0 1 1 4 3c-1 1-1 1-1 3m0 3h.01',edit:'m4 16 12-12 4 4L8 20l-5 1 1-5ZM14 6l4 4',trash:'M3 6h18M9 6V3h6v3M5 6l1 16h12l1-16M10 10v8m4-8v8',download:'M12 2v14m-5-5 5 5 5-5M3 17v5h18v-5',lock:'M5 10h14v12H5V10ZM8 10V6a4 4 0 0 1 8 0v4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.cube}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=()=>({items:[],outfits:[],collections:[],plans:[],trips:[],favorites:[],profile:{name:'',email:''},body:{},styles:[]});
let data=fresh();try{data={...data,...JSON.parse(localStorage.getItem('wardrobe-v2')||'{}')}}catch{}
let db,urls=new Map(),page=location.hash.slice(1)||'home',selected='',slide=0,query='',category='All',onlyFavorites=false,selectedCollection='',selectedTrip='',selectedOutfit='',stream=null,uploadDraft=null,activeDay=new Date(),fit={width:0,length:0,position:0,rotation:0},cameraItem='',calendarMonth=new Date();
const app=document.querySelector('#app'),overlay=document.querySelector('#overlay'),cats=['Tops','Bottoms','Outerwear','Dresses','Shoes','Accessories','Other'];
const uid=()=>crypto.randomUUID();const itemBy=id=>data.items.find(i=>i.id===id);const byOutfit=id=>data.outfits.find(o=>o.id===id);const picked=()=>itemBy(selected)||filtered()[slide]||data.items[0];
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dateText=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'Choose date';
function save(){try{localStorage.setItem('wardrobe-v2',JSON.stringify(data));return true}catch{toast('Your device storage is full. Export a backup before adding more.');return false}}
function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open('wardrobe-assets',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function storeBlob(key,blob){return new Promise((res,rej)=>{const t=db.transaction('files','readwrite');t.objectStore('files').put(blob,key);t.oncomplete=res;t.onerror=()=>rej(t.error)})}
function getBlob(key){return new Promise((res,rej)=>{const r=db.transaction('files').objectStore('files').get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function delBlob(key){return new Promise((res,rej)=>{const t=db.transaction('files','readwrite');t.objectStore('files').delete(key);t.oncomplete=res;t.onerror=()=>rej(t.error)})}
async function preload(){for(const i of data.items){for(const k of [i.photoKey,i.modelKey,i.sourceKey,i.renderKey])if(k&&!urls.has(k)){const b=await getBlob(k);if(b)urls.set(k,URL.createObjectURL(b))}}}
const photo=i=>i?(urls.get(i.renderKey)||urls.get(i.photoKey)||''):'';const model=i=>i?.modelKey?urls.get(i.modelKey)||'':'';
function btn(label,action,cls='secondary',ic='',attrs=''){return `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${label}</button>`}
const round=(ic,action,label,attrs='')=>btn('',action,'round',ic,`aria-label="${esc(label)}" title="${esc(label)}" ${attrs}`);
function heading(title,sub='',action=''){return `<div class="greeting"><div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>${action}</div>`}
const section=(title,action='',label='View all')=>`<div class="section-head"><h2>${title}</h2>${action?btn(label,action,'text-btn'):''}</div>`;
let artId=0;
function statArt(kind){const id='wardrobe-art-'+(++artId),shapes={closet:`<path d="M21 14c0-6 8-6 8-1 0 3-4 3-4 6" fill="none" stroke="#7e9fc9" stroke-width="2" stroke-linecap="round"/><path d="m24 19 15 12c2 2 1 5-2 5H11c-3 0-4-3-2-5Z" fill="url(#${id})" stroke="#fafdff" stroke-width="1.5"/><path d="m17 26 7 4 7-4-2 14H19Z" fill="#f8fbffe8" stroke="#9ab6d9" stroke-width=".8"/><path d="m21 28 3 2 3-2" fill="none" stroke="#94afd2"/>`,outfits:`<path d="m27 23 12-1 2 20-7 1-2-13-1 13-7-1Z" fill="url(#${id})" stroke="#fff" stroke-width="1.3"/><path d="m14 11 6 3 6-3 8 7-5 6-3-2v15H14V22l-3 2-5-6Z" fill="#f5e8d6" stroke="#fff" stroke-width="1.5"/><path d="M16 12q4 8 8 0M17 32h6" fill="none" stroke="#c7ad8d" stroke-linecap="round"/><path d="M33 27v11" stroke="#8cabc9" stroke-width="1"/>`,layers:`<rect x="7" y="12" width="29" height="29" rx="6" transform="rotate(-13 21 26)" fill="#c5c1df" stroke="#fff" stroke-width="1.2"/><rect x="12" y="9" width="29" height="29" rx="6" transform="rotate(7 26 23)" fill="url(#${id})" stroke="#fff" stroke-width="1.5"/><path d="m19 22 7-5 7 5-7 5Z" fill="#f6f4ff" stroke="#9e9bc5" stroke-linejoin="round"/><path d="m19 26 7 5 7-5" fill="none" stroke="#f6f4ff" stroke-width="1.5" stroke-linecap="round"/>`};return `<svg class="stat-art art-${kind}" viewBox="0 0 48 48" aria-hidden="true"><defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${kind==='layers'?'#eeebff':'#e2efff'}"/><stop offset="1" stop-color="${kind==='layers'?'#a3a5d1':'#8babd4'}"/></linearGradient></defs><ellipse cx="24" cy="42" rx="14" ry="2" fill="#708db515"/><g class="stat-art-object">${shapes[kind]||shapes.closet}</g></svg>`}
const stat=(n,label,ic)=>`<div class="stat glass">${ic?`<span class="symbol custom-symbol">${statArt(ic)}</span>`:''}<strong>${n}</strong><p>${n===1?({Pieces:'Piece',Looks:'Look',Collections:'Collection',Days:'Day',Favorites:'Favorite',Trips:'Trip','3D models':'3D model'}[label]||label):label}</p></div>`;
function empty(title,sub,action='',label='',ic='closet'){return `<div class="empty-state">${scene(({bag:"bag",calendar:"calendar",outfits:"outfits",chart:"chart"})[ic]||"closet")}<h2>${title}</h2><p>${sub}</p>${action?btn(label,action,'primary','plus'):''}</div>`}
function select(name,options,value='',label='Choose one'){return `<div class="custom-select"><input type="hidden" name="${name}" value="${esc(value)}"><button type="button" class="select-trigger" data-action="toggle-select" aria-haspopup="listbox" aria-expanded="false"><span>${esc(options.find(o=>(o.value??o)===value)?.label||value||label)}</span>${icon('chevron')}</button><div class="select-options" role="listbox" hidden>${options.map(o=>{const v=o.value??o,l=o.label??o;return `<button type="button" role="option" aria-selected="${v===value}" data-option="${esc(v)}"><span>${esc(l)}</span>${v===value?icon('check'):''}</button>`}).join('')}</div></div>`}
function datePicker(name,value=''){return `<div class="date-control"><input type="hidden" name="${name}" value="${value}"><button type="button" class="select-trigger" data-action="open-date" aria-haspopup="dialog" aria-expanded="false"><span>${dateText(value)}</span>${icon('calendar')}</button><div class="date-options" hidden></div></div>`}
function pills(labels,active,type){return `<div class="pills" role="tablist">${labels.map(x=>`<button class="pill ${active===x?'active':''}" role="tab" aria-selected="${active===x}" data-${type}="${esc(x)}">${esc(x)}</button>`).join('')}</div>`}
function thumb(i,cls=''){return photo(i)?`<img class="${cls}" src="${photo(i)}" alt="${esc(i.name)}">`:`<span class="model-thumb ${cls}">${icon('cube')}</span>`}
function miniature(i){return `<button class="piece-mini" data-item="${i.id}" aria-label="View ${esc(i.name)}">${thumb(i)}<span>${esc(i.name)}</span>${i.modelKey?'<small>3D</small>':''}</button>`}
const navs=[['home','home','Home'],['closet','closet','My Closet'],['outfits','outfits','Outfits'],['collections','layers','Collections'],['planner','calendar','Planner'],['packing','bag','Packing'],['insights','chart','Insights']];
function nav(id,ic,title){return `<button class="nav-item ${page===id?'active':''}" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(ic)}<span>${title}</span>${id==='closet'?`<span class="badge">${data.items.length}</span>`:''}</button>`}
const titles={home:'Home',closet:'My Closet',viewer:'My Closet',outfits:'Outfits',collections:'Collections',planner:'Outfit Planner',packing:'Packing',insights:'Insights',profile:'Profile',tryon:'Try-On',permission:'Camera Access',look:'Your Outfit',welcome:'Welcome',saved:'Saved Looks',compare:'Compare Looks'};
function shell(content){return `<div class="layout page-${page}"><aside class="sidebar"><button class="brand" data-page="home" style="background:none;text-align:left"><img src="assets/logo.webp" alt="Wardrobe glass hanger logo"><div><strong>Wardrobe</strong><span>YOUR CLOTHES. REIMAGINED.</span></div></button><p class="nav-label">YOUR SPACE</p><nav aria-label="Main navigation">${navs.map(n=>nav(...n)).join('')}</nav>${btn('Add','add-menu','sidebar-add','plus')}<div class="sidebar-bottom"><button class="mini-profile" data-page="profile" style="background:none;width:100%;text-align:left"><span class="avatar">${data.profile.name?esc(data.profile.name.split(' ').map(n=>n[0]).slice(0,2).join('')):icon('profile')}</span><div><strong>${esc(data.profile.name||'Your Wardrobe')}</strong><p>Made personal by you</p></div>${icon('chevron')}</button></div></aside><main class="workspace"><header class="topbar"><div class="breadcrumb">Wardrobe ${icon('chevron')} <span>${titles[page]||'Home'}</span></div></header><div class="screen-enter" id="view">${content}</div></main><nav class="bottom-nav" aria-label="Mobile navigation">${[['home','home','Home'],['closet','closet','Closet'],['add','plus','Add'],['outfits','outfits','Outfits'],['profile','profile','Profile']].map(([id,ic,l])=>`<button ${id==='add'?'data-action="add-menu"':`data-page="${id}"`} class="${page===id?'active':''}" aria-label="${id==='add'?'Add or try on':l}">${id==='add'?`<span class="add-circle">${icon(ic)}</span>`:icon(ic)}<span>${l}</span></button>`).join('')}</nav></div>`}
function home(){const name=data.profile.name.split(' ')[0];return heading(name?`Hello, ${name}.`:'Your clothes. Your world.','A little space for everything you love.','')+`<div class="stats">${stat(data.items.length,'Pieces','closet')}${stat(data.outfits.length,'Looks','outfits')}${stat(data.collections.length,'Collections','layers')}</div>${!data.items.length?`<div class="home-intro glass"><div class="intro-art"><img src="assets/logo.webp" alt="Wardrobe"><span class="glass-orbit orbit-one"></span><span class="glass-orbit orbit-two"></span></div><div><p class="eyebrow">A WARDROBE, ENTIRELY YOURS</p><h2>Every piece has<br>a place here.</h2><p>Add your first piece.<br>Make the rest yours.</p>${btn('Add your first piece','upload','primary','plus')}</div></div>`:`${section('Your latest pieces','closet')}<div class="miniature-grid">${data.items.slice(-4).reverse().map(miniature).join('')}</div>`}<div class="home-links">${[['layers','Collect the possibilities.','Create a home for your favorite pieces.','collections'],['calendar','A little more prepared.','Make tomorrow’s outfit one less thought.','planner'],['bag','Take your wardrobe along.','A packing list made from what you own.','packing']].map(([ic,t,s,a])=>`<button class="home-link glass" data-page="${a}"><span class="round">${icon(ic)}</span><h3>${t}</h3><p>${s}</p>${icon('arrow')}</button>`).join('')}</div>`}
function filtered(){return data.items.filter(i=>(category==='All'||i.category===category)&&(!onlyFavorites||data.favorites.includes(i.id))&&`${i.name} ${i.brand} ${i.color}`.toLowerCase().includes(query.toLowerCase()))}
function stage(i){if(i&&!photo(i)&&!model(i))return pendingStage(i);if(!i)return `<div class="garment-stage glass"><div class="stage-aura"></div>${data.items.length?empty('Nothing in this view.','Try another search or category.'):empty('Your closet starts here.','Add a garment photo to begin.','upload','Add a piece')}</div>`;return `<div class="garment-stage glass" id="garment-stage"><div class="stage-aura"></div><div class="stage-label">${icon(i.modelKey?'cube':'image')}<span>${i.modelKey?'3D GARMENT':'GARMENT RENDER'}</span></div>${round('heart','favorite','Favorite piece',`aria-pressed="${data.favorites.includes(i.id)}"`)}<div class="slide-content" data-direction="${slideDirection}">${model(i)?`<model-viewer id="garment-model" src="${model(i)}" alt="${esc(i.name)}" camera-controls auto-rotate auto-rotate-delay="2000" rotation-per-second="12deg" shadow-intensity="1" shadow-softness="1" exposure="1" environment-image="neutral" interaction-prompt="none" camera-orbit="25deg 75deg auto" touch-action="pan-y" loading="eager"></model-viewer>`:`<img class="garment-photo" src="${photo(i)}" alt="${esc(i.name)}" draggable="false">`}</div><div class="stage-floor"></div><div class="stage-navigation"><div class="slide-dots" aria-label="Garment slides">${filtered().map((x,n)=>`<button data-slide="${n}" class="slide-dot ${x.id===i.id?'active':''}" aria-label="View ${esc(x.name)}" aria-current="${x.id===i.id?'true':'false'}"></button>`).join('')}</div></div></div>`}
let slideDirection='next';
let editingItem=false;
function garmentDetails(i){if(!i)return '';if(editingItem)return `<form id="item-form" class="inline-edit"><div class="inline-edit-top"><span class="eyebrow">YOUR PIECE</span><div>${round('close','cancel-edit','Cancel editing')}<button class="inline-save" type="submit" aria-label="Save changes" title="Save changes">${icon('check')}</button></div></div><label class="field">Name<input name="name" value="${esc(i.name)}" maxlength="70" required></label><div class="form-pair"><label class="field">Category${select('category',cats,i.category)}</label><label class="field">Color<input name="color" value="${esc(i.color)}" maxlength="35" placeholder="Optional"></label></div><label class="field">Brand<input name="brand" value="${esc(i.brand)}" maxlength="50" placeholder="Optional"></label></form>`;return `<div class="garment-detail-top"><div>${i.brand?`<p class="eyebrow">${esc(i.brand)}</p>`:''}<h2>${esc(i.name)}</h2></div><div class="garment-detail-actions">${round('edit','edit-item','Edit this piece')}${round('more','item-options','Piece options')}</div></div><div class="piece-tags">${i.category!=='Other'?`<span>${icon('outfits')}${esc(i.category)}</span>`:''}${i.color?`<span>${esc(i.color)}</span>`:''}${i.modelKey?`<span>${icon('cube')}3D</span>`:''}</div>${i.notes?`<p class="piece-note">${esc(i.notes)}</p>`:''}${i.renderKey?'<p class="asset-note">A dimensional preview, made from your photo.</p>':''}`}
function closet(viewer=false){const list=filtered();if(slide>=list.length)slide=0;const i=list[slide];if(i)selected=i.id;return heading('My Closet')+`<div class="toolbar"><label class="search">${icon('search')}<input id="search" placeholder="Find a piece…" aria-label="Search wardrobe" value="${esc(query)}"></label><div class="closet-tools">${round('heart','favorites-only','Show favorites',`aria-pressed="${onlyFavorites}"`)}${round('sliders','closet-options','Closet view')}</div></div>${pills(['All',...cats],category,'category')}<div class="closet-presentation garment-card glass ${i?'':'empty-garment-card'}"><div class="garment-visual">${stage(i)}</div>${i?`<section class="garment-info" aria-label="Garment details">${garmentDetails(i)}</section>`:''}</div>`}
function outfitArt(o){const its=o.itemIds.map(itemBy).filter(Boolean);if(!its.length)return `<div class="outfit-mosaic outfit-blank">${icon('outfits')}<span>No pieces yet</span></div>`;return `<div class="outfit-mosaic">${its.slice(0,4).map(i=>`<div>${thumb(i)}</div>`).join('')}</div>`}
function outfits(){return heading('Your Looks','Good pieces. Better together.',data.outfits.length?round('plus','new-outfit','Create an outfit'):'')+(!data.outfits.length?`<div class="glass">${empty('A look that feels like you.','Bring your own pieces together into an outfit.','new-outfit','Create a look','outfits')}</div>`:`<div class="collection-grid">${data.outfits.map(o=>`<article class="collection glass"><button class="outfit-open" data-outfit="${o.id}" aria-label="Open ${esc(o.name)}">${outfitArt(o)}</button><div class="collection-footer"><div><h3>${esc(o.name)}</h3><p>${o.itemIds.length} pieces</p></div>${round('more','outfit-options','Outfit options',`data-id="${o.id}"`)}</div></article>`).join('')}</div>`)}
function look(){const o=byOutfit(selectedOutfit);if(!o)return outfits();return btn('Your looks','outfits','back','back')+heading(o.name,`${o.itemIds.length} ${o.itemIds.length===1?'piece':'pieces'}, brought together.`,round('more','outfit-options','Outfit options',`data-id="${o.id}"`))+`<div class="glass look-real">${outfitArt(o)}<div class="look-actions">${btn('Plan this look','plan','secondary','calendar')}</div></div>`}
function collections(){const c=data.collections.find(c=>c.id===selectedCollection);if(c)return btn('All collections','all-collections','back','back')+heading(c.name,`${c.itemIds.length} pieces`,c.itemIds.length?round('plus','collection-pieces','Choose pieces'):'')+`<div class="miniature-grid">${c.itemIds.map(itemBy).filter(Boolean).map(miniature).join('')||empty('Make it your own.','Choose pieces from your closet.','collection-pieces','Choose pieces','layers')}</div>`;return heading('Collections','Your wardrobe, thoughtfully arranged.',data.collections.length?round('plus','new-collection','New collection'):'')+(!data.collections.length?`<div class="glass">${empty('Room for a little inspiration.','Create a collection for a season, a feeling, or a favorite style.','new-collection','Create a collection','layers')}</div>`:`<div class="collection-grid">${data.collections.map(c=>`<article class="collection glass"><button class="outfit-open" data-collection="${c.id}" aria-label="Open ${esc(c.name)}">${c.itemIds.length?outfitArt(c):`<div class="collection-blank">${icon('layers')}</div>`}</button><div class="collection-footer"><div><h3>${esc(c.name)}</h3><p>${c.itemIds.length} ${c.itemIds.length===1?'piece':'pieces'}</p></div>${round('more','collection-options','Collection options',`data-id="${c.id}"`)}</div></article>`).join('')}</div>`)}
function planner(){const start=new Date(activeDay);start.setDate(start.getDate()-start.getDay());const days=Array.from({length:7},(_,n)=>{const d=new Date(start);d.setDate(d.getDate()+n);return d});const plans=data.plans.filter(p=>p.date===dateKey(activeDay));return heading('Outfit Planner','A little more ready for your day.',plans.length?round('plus','plan','Plan an outfit'):'')+`<div class="planner-head glass"><div class="calendar-month"><h2>${activeDay.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><div>${round('back','prev-week','Previous week')}${round('chevron','next-week','Next week')}${round('calendar','planner-date','Choose date')}</div></div><div class="week">${days.map(d=>`<button class="day ${dateKey(d)===dateKey(activeDay)?'active':''}" data-day="${dateKey(d)}"><span>${d.toLocaleDateString('en-US',{weekday:'short'})}</span>${d.getDate()}${data.plans.some(p=>p.date===dateKey(d))?'<i class="plan-indicator"></i>':''}</button>`).join('')}</div></div><div class="plan-list">${plans.map(p=>{const o=byOutfit(p.outfitId);if(!o)return '';return `<article class="plan-row glass"><div class="plan-date">${activeDay.getDate()}<small>${activeDay.toLocaleDateString('en-US',{weekday:'short'})}</small></div><div class="plan-outfit-art">${outfitArt(o)}</div><div><h3>${esc(o.name)}</h3><p>${esc(p.note||'A look for your day.')}</p></div>${round('trash','delete-plan','Remove from planner',`data-id="${p.id}"`)}</article>`}).join('')||`<div class="glass">${empty('An open day. An open closet.','Choose a look for '+dateText(dateKey(activeDay))+'.','plan','Plan a look','calendar')}</div>`}</div>`}
function packing(){const t=data.trips.find(t=>t.id===selectedTrip)||data.trips[0];if(!t)return heading('Packing','Take a little of you, wherever you go.','')+`<div class="glass">${empty('Where to next?','Build a packing list from your own wardrobe.','new-trip','Create a trip','bag')}</div>`;selectedTrip=t.id;const its=t.itemIds.map(itemBy).filter(Boolean);return heading(t.name,`${dateText(t.start)} — ${dateText(t.end)}`,round('more','trip-options','Trip options'))+`<div class="trip-tabs">${data.trips.map(tr=>btn(esc(tr.name),'switch-trip','pill '+(t.id===tr.id?'active':''),'',`data-id="${tr.id}"`)).join('')}${round('plus','new-trip','New trip')}</div><div class="packing-stats stats">${stat(its.length,'Pieces')}${stat(t.packed.length,'Packed')}${stat(Math.max(1,Math.round((new Date(t.end)-new Date(t.start))/86400000)+1),'Days')}</div><div class="progress"><div style="width:${its.length?t.packed.length/its.length*100:0}%"></div></div><div class="section-head"><p class="small muted">${t.packed.length} of ${its.length} pieces ready</p>${its.length?btn('Choose pieces','trip-pieces','text-btn','plus'):''}</div><div class="packing-real-grid">${its.map(i=>`<article class="pack-piece glass">${thumb(i)}<div><h3>${esc(i.name)}</h3><p>${esc(i.category)}</p></div><button class="pack-check ${t.packed.includes(i.id)?'checked':''}" data-pack="${i.id}" aria-label="${t.packed.includes(i.id)?'Unpack':'Pack'} ${esc(i.name)}" aria-pressed="${t.packed.includes(i.id)}">${icon('check')}</button></article>`).join('')||empty('Bring your favorites.','Choose pieces from your closet for this trip.','trip-pieces','Choose pieces','bag')}</div>`}
function insights(){const counts=cats.map(c=>[c,data.items.filter(i=>i.category===c).length]);const colors={};for(const i of data.items)if(i.color)colors[i.color]=(colors[i.color]||0)+1;return heading('Insights','Your wardrobe, at a glance.')+`<div class="insight-cards">${stat(data.items.length,'Pieces')}${stat(data.outfits.length,'Looks')}${stat(data.favorites.length,'Favorites')}${stat(data.items.filter(i=>i.modelKey).length,'3D models')}</div>${!data.items.length?`<div class="glass">${empty('The story starts with your closet.','Add your pieces to see your wardrobe take shape.','upload','Add a piece','chart')}</div>`:`<div class="split"><div class="chart-card glass">${section('By Category')}<div class="real-bars">${counts.filter(([,n])=>n).map(([c,n])=>`<div><span>${c}</span><div><i style="width:${n/data.items.length*100}%"></i></div><strong>${n}</strong></div>`).join('')}</div></div><div class="chart-card glass">${section('Your Colors')}<div class="real-colors">${Object.entries(colors).map(([c,n])=>`<div><span>${esc(c)}</span><strong>${n} ${n===1?'piece':'pieces'}</strong></div>`).join('')||'<p class="muted small">Add a color in your garment details to see your palette here.</p>'}</div></div></div>`}`}
function profile(){return `<div class="profile-card glass"><div class="profile-header"><span class="avatar">${icon('profile')}</span><div><h2>${esc(data.profile.name||'Your Wardrobe')}</h2><p>${esc(data.profile.email||'A little more personal.')}</p></div>${round('edit','edit-profile','Edit profile')}</div><div class="insight-cards">${stat(data.items.length,'Pieces')}${stat(data.outfits.length,'Looks')}${stat(data.collections.length,'Collections')}${stat(data.trips.length,'Trips')}</div>${[['grid','Explore your wardrobe','Your pieces, plans, and collections','navigation'],['sparkle','Style preferences',data.styles.length?data.styles.join(', '):'Find the styles that feel like you','styles'],['profile','Body profile','Your own sizing notes','body'],['cloud','Backup & restore','Stored on this device','backup'],['help','A little guidance','Make yourself at home','help']].map(([ic,t,s,a])=>`<button class="settings-row ${a==='navigation'?'mobile-only':''}" data-action="${a}">${icon(ic)}<div><h3>${esc(t)}</h3><p>${esc(s)}</p></div>${icon('chevron')}</button>`).join('')}</div>`}
const views={home,closet,viewer:()=>closet(true),outfits,look,collections,planner,packing,insights,profile,tryon:()=>lucyView(),permission:()=>lucyView(),welcome:home,saved:outfits,compare:outfits};
function render(options={}){if(!views[page])page='home';const existing=app.querySelector('.layout'),same=existing?.classList.contains('page-'+page),oldVideo=same&&page==='tryon'?document.querySelector('#camera-video'):null;const content=views[page]();if(same){document.querySelector('#view').innerHTML=content;document.querySelectorAll('.nav-item .badge').forEach(el=>el.textContent=data.items.length)}else app.innerHTML=shell(content);if(options.instant)document.querySelector('.slide-content')?.style.setProperty('animation','none');document.title=`${titles[page]||'Wardrobe'} · Wardrobe`;if((remoteStream||stream)&&page==='tryon'){let v=document.querySelector('#camera-video');if(v){if(oldVideo){v.replaceWith(oldVideo);v=oldVideo}if(v.srcObject!==(remoteStream||stream)){v.srcObject=remoteStream||stream;v.play().catch(()=>{})}}}bindStage();if(matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelector('model-viewer')?.removeAttribute('auto-rotate');document.querySelector('model-viewer')?.addEventListener('error',()=>toast('This model could not be rendered. Try a valid, self-contained GLB file.'))}
function go(p){editingItem=false;closeModal();if(p!=='tryon')stopCamera();page=p;query='';category='All';onlyFavorites=false;selectedCollection='';location.hash=p;render();window.scrollTo({top:0,behavior:'instant'})}
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3400)}
function modal(title,body){overlay.innerHTML=`<div class="scrim"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-top"><h2>${esc(title)}</h2>${round('close','close-modal','Close dialog')}</div>${body}</section></div>`;overlay.querySelector('input:not([type=hidden]):not([type=file]),textarea,button')?.focus()}
function closeModal(){const scrim=overlay.querySelector('.scrim');if(!scrim||scrim.classList.contains('closing'))return;scrim.classList.add('closing');scrim.inert=true;setTimeout(()=>scrim.remove(),matchMedia('(prefers-reduced-motion: reduce)').matches?0:400)}
function addMenu(){modal('Make it yours.',`<div class="add-options"><button class="add-option" data-action="upload"><span class="add-symbol">${icon('closet')}</span><div><h3>Add a piece</h3><p>A photo of something you love.</p></div>${icon('chevron')}</button><button class="add-option" data-action="open-camera"><span class="add-symbol">${icon('camera')}</span><div><h3>Real-time Try-On</h3><p>Your camera. Your wardrobe.</p></div>${icon('chevron')}</button></div>`)}
function upload(){if(uploadDraft?.url)URL.revokeObjectURL(uploadDraft.url);uploadDraft=null;modal('Add a piece.',`<label class="dropzone" for="garment-file"><div class="upload-orb">${icon('closet')}</div><h3>Something you love.</h3><p>One photo. We’ll take it from here.</p><span class="upload-hint">JPG, PNG, WebP · 15 MB</span></label><input class="file-input" id="garment-file" type="file" accept="image/jpeg,image/png,image/webp"><label class="camera-upload" for="camera-file">${icon('camera')} Take a photo</label><input class="file-input" id="camera-file" type="file" accept="image/*" capture="environment">`)}
async function prepareUpload(file,attach=false){if(!file)return;const isModel=/\.glb$/i.test(file.name);try{if(isModel){if(file.size>50*1024*1024)throw Error('Choose a GLB under 50 MB.');const header=new DataView(await file.slice(0,12).arrayBuffer());if(header.byteLength<12||header.getUint32(0,true)!==0x46546c67||header.getUint32(4,true)!==2||header.getUint32(8,true)!==file.size)throw Error('This file is not a valid GLB 2.0 model.')}else{if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>15*1024*1024)throw Error('Choose a JPG, PNG or WebP under 15 MB.');if(attach)throw Error('Choose a .glb model to attach.')}if(attach){const i=picked(),key=uid();await storeBlob(key,file);if(i.modelKey){await delBlob(i.modelKey);URL.revokeObjectURL(urls.get(i.modelKey));urls.delete(i.modelKey)}i.modelKey=key;urls.set(key,URL.createObjectURL(file));save();closeModal();render();toast('3D model attached.');return}let blob=file;if(!isModel){const img=await createImageBitmap(file);const ratio=Math.min(1,1200/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);blob=await new Promise(r=>canvas.toBlob(r,'image/webp',.88));img.close();if(!blob)throw Error('This photo could not be opened.')}uploadDraft={blob,isModel,url:URL.createObjectURL(blob)};modal('The little details.',`<div class="upload-preview">${isModel?`<model-viewer src="${uploadDraft.url}" alt="Your uploaded garment" camera-controls auto-rotate interaction-prompt="none" shadow-intensity="1"></model-viewer>`:`<img src="${uploadDraft.url}" alt="Your garment photo">`}</div><form id="upload-form"><label class="field">Name<input name="name" required maxlength="70" value="${esc(file.name.replace(/\.[^.]+$/,'').replace(/[_-]/g,' '))}" placeholder="Your piece"></label><div class="form-pair"><label class="field">Category${select('category',cats,'Tops')}</label><label class="field">Color<input name="color" maxlength="35" placeholder="Optional"></label></div><label class="field">Brand<input name="brand" maxlength="50" placeholder="Optional"></label><button class="primary" type="submit">Save to closet ${icon('check')}</button></form>`);if(isModel)loadModelViewer()}catch(err){toast(err.message||'This file could not be opened.')}}
function editItem(){const i=picked();modal('Your piece.',`<form id="item-form"><label class="field">Name<input name="name" required maxlength="70" value="${esc(i.name)}"></label><div class="form-pair"><label class="field">Category${select('category',cats,i.category)}</label><label class="field">Color<input name="color" maxlength="35" value="${esc(i.color)}"></label></div><div class="form-pair"><label class="field">Brand<input name="brand" maxlength="50" value="${esc(i.brand)}"></label><label class="field">Value ($)<input name="price" type="number" min="0" max="1000000" step=".01" value="${Number(i.price||0)}"></label></div><label class="field">Notes<textarea name="notes" maxlength="1500" rows="3" placeholder="A detail worth remembering.">${esc(i.notes)}</textarea></label><button class="primary">Save changes ${icon('check')}</button></form>`)}
function choosePieces(formId,ids=[],name=''){if(!data.items.length){modal('A closet comes first.',`<p>Add a garment, then bring your pieces together.</p>${btn('Add a piece','upload','primary','plus')}`);return}modal(name||'Choose your pieces.',`<form id="${formId}">${formId==='outfit-form'?`<label class="field">Outfit name<input name="name" required maxlength="70" placeholder="Give your look a name" value="${esc(byOutfit(selectedOutfit)?.name||'')}"></label>`:''}<div class="piece-check-list">${data.items.map(i=>`<label class="piece-check">${thumb(i)}<span>${esc(i.name)}<small>${esc(i.category)}</small></span><input type="checkbox" name="items" value="${i.id}" ${ids.includes(i.id)?'checked':''}><i>${icon('check')}</i></label>`).join('')}</div><button class="primary">${formId==='outfit-form'?'Save look':'Save pieces'} ${icon('check')}</button></form>`)}
function planModal(){if(!data.outfits.length){modal('Start with a look.',`<p>Create an outfit from your wardrobe, then give it a day.</p>${btn('Create a look','new-outfit','primary','outfits')}`);return}modal('A look for your day.',`<form id="plan-form"><label class="field">Outfit${select('outfitId',data.outfits.map(o=>({value:o.id,label:o.name})),selectedOutfit||data.outfits[0].id)}</label><label class="field">Date${datePicker('date',dateKey(activeDay))}</label><label class="field">Note<input name="note" maxlength="100" placeholder="Optional"></label><button class="primary">Add to planner ${icon('calendar')}</button></form>`)}
function tripForm(edit=false){const t=edit?data.trips.find(t=>t.id===selectedTrip):null;modal(edit?'Your trip.':'Somewhere new.',`<form id="trip-form" data-edit="${t?.id||''}"><label class="field">Trip name<input name="name" required maxlength="70" value="${esc(t?.name||'')}" placeholder="Where are you headed?"></label><div class="form-pair"><label class="field">Departure${datePicker('start',t?.start||dateKey(new Date()))}</label><label class="field">Return${datePicker('end',t?.end||dateKey(new Date()))}</label></div><button class="primary">${edit?'Save trip':'Create trip'} ${icon('arrow')}</button></form>`)}
function calendar(control,delta=0){const current=control.dataset.month?new Date(control.dataset.month+'-01T12:00:00'):new Date((control.querySelector('input').value||dateKey(new Date()))+'T12:00:00');current.setDate(1);current.setMonth(current.getMonth()+delta);control.dataset.month=dateKey(current).slice(0,7);const first=current.getDay(),days=new Date(current.getFullYear(),current.getMonth()+1,0).getDate(),chosen=control.querySelector('input').value;control.querySelector('.date-options').innerHTML=`<div class="date-month">${round('back','calendar-prev','Previous month')}<strong>${current.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</strong>${round('chevron','calendar-next','Next month')}</div><div class="date-grid">${['S','M','T','W','T','F','S'].map(d=>`<span>${d}</span>`).join('')}${Array.from({length:first},()=>'<i></i>').join('')}${Array.from({length:days},(_,n)=>{const k=control.dataset.month+'-'+String(n+1).padStart(2,'0');return `<button type="button" data-date-choice="${k}" class="${k===chosen?'active':''} ${k===dateKey(new Date())?'today':''}" aria-label="${dateText(k)}">${n+1}</button>`}).join('')}</div>`}
function closeDropdowns(except){document.querySelectorAll('.select-options,.date-options').forEach(el=>{if(el!==except){el.hidden=true;el.previousElementSibling?.setAttribute('aria-expanded','false')}})}
function loadModelViewer(){if(!customElements.get('model-viewer'))import('./vendor/model-viewer.min.js').catch(()=>toast('The 3D viewer could not be loaded.'))}
let stopTilt=null;
function bindStage(){stopTilt?.();stopTilt=null;const stage=document.querySelector('#garment-stage'),img=document.querySelector('.garment-photo');if(!stage)return;if(stage.querySelector('model-viewer'))loadModelViewer();if(!img)return;let down=false,startX=0,startY=0,lastX=0,target=0,angle=0,velocity=0,frame=0,last=performance.now();const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const tick=now=>{const dt=Math.min((now-last)/16.67,2);last=now;if(!down){target*=Math.pow(.956,dt)}angle+=(target-angle)*(reduced?.4:.07)*dt;img.style.transform=`perspective(1000px) rotateY(${angle}deg) rotateZ(${-angle*.06}deg) translateY(${-Math.abs(angle)*.025}px)`;img.style.filter=`drop-shadow(${-angle*.55}px 25px 24px #52688430)`;if(Math.abs(angle)>.025||down||Math.abs(target)>.025)frame=requestAnimationFrame(tick);else frame=0};stage.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;down=true;startX=lastX=e.clientX;startY=e.clientY;velocity=0;img.classList.add('dragging');stage.setPointerCapture(e.pointerId);if(!frame){last=performance.now();frame=requestAnimationFrame(tick)}});stage.addEventListener('pointermove',e=>{if(!down)return;const dx=e.clientX-lastX;velocity=dx;target=Math.max(-28,Math.min(28,target+dx*.18));lastX=e.clientX});const release=e=>{if(!down)return;down=false;img.classList.remove('dragging');const dx=e.clientX-startX,dy=e.clientY-startY;if(Math.abs(dx)>100&&Math.abs(dx)>Math.abs(dy)*1.5&&filtered().length>1){moveSlide(dx<0?1:-1)}else target=Math.max(-28,Math.min(28,target+velocity*.6))};stage.addEventListener('pointerup',release);stage.addEventListener('pointercancel',()=>{down=false;target=0});stopTilt=()=>{cancelAnimationFrame(frame)}}
function moveSlide(n){editingItem=false;const list=filtered();if(list.length<2)return;slideDirection=n<0?'prev':'next';slide=(slide+n+list.length)%list.length;selected=list[slide].id;render()}
let lucySession=null,remoteStream=null,lucyConnecting=false,lucyStatus='idle',sessionAttempt=0;
function stopCamera(){sessionAttempt++;const active=lucySession;lucySession=null;active?.disconnect();stream?.getTracks().forEach(t=>t.stop());stream=null;remoteStream?.getTracks().forEach(t=>t.stop());remoteStream=null;lucyConnecting=false;lucyStatus='idle'}
async function startLucy(){if(lucyConnecting||lucySession)return;const i=itemBy(cameraItem)||data.items.find(i=>photo(i));if(!i){toast('Add a garment photo to try it on.');return}lucyConnecting=true;lucyStatus='connecting';const attempt=++sessionAttempt;render();try{const status=await fetch('/api/lucy/status').then(r=>r.json());if(status.locked){lucyConnecting=false;lucyStatus='idle';render();unlockModal(startLucy);return}if(attempt!==sessionAttempt||page!=='tryon')return;if(!status.ready){lucyConnecting=false;lucyStatus='idle';render();modal('Connect Lucy.',`<p>Try-On is ready to connect to Lucy. Add your Decart API key as the server’s <code>DECART_API_KEY</code> secret to enable it.</p><p class="asset-note">The permanent key stays on the server.</p>${btn('Back to wardrobe','close-modal','primary')}`);return}const {createDecartClient,models}=await import('./vendor/lucy.js');const m=models.realtime('lucy-vton-latest');stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{width:{ideal:m.width},height:{ideal:m.height},frameRate:{ideal:m.fps},facingMode:'user'}});if(page!=='tryon'){stopCamera();return}const client=createDecartClient({apiKeyProvider:async()=>{const res=await fetch('/api/lucy/token',{method:'POST',headers:{'Content-Type':'application/json'}});if(!res.ok)throw Error('Lucy could not connect. Check the server connection.');const token=await res.json();return token.apiKey}});const connected=await client.realtime.connect(stream,{model:m,mirror:'auto',onRemoteStream:s=>{if(attempt!==sessionAttempt||page!=='tryon'){s.getTracks().forEach(t=>t.stop());return}remoteStream=s;lucyStatus='live';render()}});if(attempt!==sessionAttempt||page!=='tryon'){connected.disconnect();return}lucySession=connected;lucySession.on?.('error',()=>{toast('Lucy’s connection was interrupted. Please reconnect.');stopCamera();render()});lucySession.on?.('connectionChange',s=>{if(s==='disconnected'){stopCamera();if(page==='tryon')render()}});await applyGarment();lucyConnecting=false;if(!remoteStream)lucyStatus='waiting';render()}catch(err){if(attempt!==sessionAttempt)return;stopCamera();render();toast(err.name==='NotAllowedError'?'Camera access was declined. Allow it in your browser settings to try again.':err.message||'Lucy could not connect. Please try again.')}}
async function applyGarment(){if(!lucySession)return;const i=itemBy(cameraItem),blob=i&&await getBlob(i.renderKey||i.photoKey);if(!blob)return;const kind={Tops:'top',Bottoms:'bottoms',Outerwear:'outerwear',Dresses:'dress',Shoes:'shoes',Accessories:'accessory'}[i.category]||'garment';const description=[i.color,i.name].filter(Boolean).join(' ');await lucySession.set({prompt:i.category==='Accessories'?`Add the ${description} ${kind} from the reference image.`:`Substitute the current ${kind} with the ${description} from the reference image.`,image:new File([blob],'garment.webp',{type:blob.type}),enhance:false})}

async function capture(){const video=document.querySelector('#camera-video');if(!remoteStream||!video?.videoWidth){toast('Start Try-On before capturing a look.');return}const c=document.createElement('canvas');c.width=video.videoWidth;c.height=video.videoHeight;c.getContext('2d').drawImage(video,0,0);const blob=await new Promise(r=>c.toBlob(r,'image/png'));const url=URL.createObjectURL(blob);modal('A look, made yours.',`<img src="${url}" alt="Your Lucy try-on capture" style="width:100%;max-height:55vh;object-fit:contain;border-radius:18px"><a class="primary" href="${url}" download="wardrobe-look.png" style="text-decoration:none">Save photo ${icon('download')}</a>`)}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
async function exportData(){const assets={};for(const i of data.items)for(const k of [i.photoKey,i.modelKey,i.sourceKey,i.renderKey])if(k&&!assets[k]){const b=await getBlob(k);if(b)assets[k]=await new Promise(r=>{const reader=new FileReader();reader.onload=()=>r(reader.result);reader.readAsDataURL(b)})}download(new Blob([JSON.stringify({version:2,data,assets})],{type:'application/json'}),'wardrobe-backup.json');toast('Your backup is ready.')}
async function restore(file){try{if(file.size>150*1024*1024)throw Error();const backup=JSON.parse(await file.text()),d=backup.data;if(backup.version!==2||!d||!Array.isArray(d.items)||!Array.isArray(d.outfits)||!Array.isArray(d.collections)||typeof d.profile?.name!=='string')throw Error();for(const i of d.items)if(typeof i.id!=='string'||typeof i.name!=='string'||!cats.includes(i.category))throw Error();for(const [key,val] of Object.entries(backup.assets||{})){if(typeof val!=='string'||!/^data:(image\/(webp|png|jpeg)|model\/gltf-binary|application\/octet-stream);base64,/.test(val))throw Error();const b=await fetch(val).then(r=>r.blob());await storeBlob(key,b)}data={...fresh(),...d};await preload();save();go('home');toast('Your wardrobe is restored.')}catch{toast('Choose a valid Wardrobe backup.')}}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-item],[data-collection],[data-outfit]');if(!el){if(e.target.classList.contains('scrim'))closeModal();if(!e.target.closest('.custom-select,.date-control'))closeDropdowns();return}if(el.dataset.option!==undefined){const c=el.closest('.custom-select');c.querySelector('input').value=el.dataset.option;c.querySelector('.select-trigger span').textContent=el.textContent.trim();c.querySelectorAll('[role=option]').forEach(o=>{o.setAttribute('aria-selected',o===el);o.querySelector('svg')?.remove()});el.insertAdjacentHTML('beforeend',icon('check'));closeDropdowns();c.querySelector('.select-trigger').focus();if(c.querySelector('input').name==='order'){data.order=el.dataset.option;if(data.order==='new')data.items.sort((a,b)=>b.createdAt-a.createdAt);else data.items.sort((a,b)=>a[data.order].localeCompare(b[data.order]));save();slide=0;closeModal();render()}return}if(el.dataset.dateChoice){const c=el.closest('.date-control');c.querySelector('input').value=el.dataset.dateChoice;c.querySelector('.select-trigger span').textContent=dateText(el.dataset.dateChoice);closeDropdowns();c.querySelector('.select-trigger').focus();if(c.querySelector('input').name==='order'){data.order=el.dataset.option;if(data.order==='new')data.items.sort((a,b)=>b.createdAt-a.createdAt);else data.items.sort((a,b)=>a[data.order].localeCompare(b[data.order]));save();slide=0;closeModal();render()}return}if(el.dataset.page){go(el.dataset.page);return}if(el.dataset.item){selected=el.dataset.item;slide=data.items.findIndex(i=>i.id===selected);go('viewer');return}if(el.dataset.outfit){selectedOutfit=el.dataset.outfit;go('look');return}if(el.dataset.collection){selectedCollection=el.dataset.collection;page='collections';location.hash=page;render();return}if(el.dataset.category){category=el.dataset.category;editingItem=false;slide=0;refreshCloset();return}if(el.dataset.slide!==undefined){slideDirection=Number(el.dataset.slide)<slide?'prev':'next';slide=Number(el.dataset.slide);render();return}if(el.dataset.day){activeDay=new Date(el.dataset.day+'T12:00:00');render();return}if(el.dataset.pack){const t=data.trips.find(t=>t.id===selectedTrip);t.packed=t.packed.includes(el.dataset.pack)?t.packed.filter(id=>id!==el.dataset.pack):[...t.packed,el.dataset.pack];save();render();return}if(el.dataset.cameraItem){cameraItem=el.dataset.cameraItem;render();try{await applyGarment()}catch{toast('The garment could not be applied. Try again.')}return}const a=el.dataset.action;if(!a)return;if(views[a]){go(a);return}switch(a){
case 'retry-render':closeModal();startRender(picked());break;
case 'close-modal':closeModal();break;
case 'add-menu':addMenu();break;
case 'upload':upload();break;
case 'navigation':modal('Your wardrobe.',navs.map(([id,ic,t])=>btn(t,id,'settings-row',ic)).join(''));break;
case 'toggle-select':{const c=el.nextElementSibling,open=c.hidden;closeDropdowns(c);c.hidden=!open;el.setAttribute('aria-expanded',open);if(open){const r=el.getBoundingClientRect();c.style.width=Math.max(r.width,160)+'px';c.style.left=Math.min(r.left,innerWidth-Math.max(r.width,160)-16)+'px';c.style.top=Math.max(16,Math.min(r.bottom+6,innerHeight-c.offsetHeight-18))+'px';c.querySelector('[aria-selected=true]')?.focus()}break}
case 'open-date':{const c=el.closest('.date-control'),box=c.querySelector('.date-options'),open=box.hidden;closeDropdowns(box);calendar(c);box.hidden=!open;el.setAttribute('aria-expanded',open);if(open){const r=el.getBoundingClientRect();box.style.left=Math.max(16,Math.min(r.left,innerWidth-306))+'px';box.style.top=Math.max(16,Math.min(r.bottom+6,innerHeight-box.offsetHeight-18))+'px'}break}
case 'calendar-prev':case 'calendar-next':calendar(el.closest('.date-control'),a==='calendar-prev'?-1:1);break;
case 'prev-slide':moveSlide(-1);break;
case 'next-slide':moveSlide(1);break;
case 'favorite':{const i=picked();data.favorites=data.favorites.includes(i.id)?data.favorites.filter(id=>id!==i.id):[...data.favorites,i.id];save();el.setAttribute('aria-pressed',data.favorites.includes(i.id));break}
case 'favorites-only':onlyFavorites=!onlyFavorites;slide=0;refreshCloset();break;
case 'closet-options':modal('Your view.',`<label class="field">Order${select('order',[{value:'new',label:'Newest first'},{value:'name',label:'Name, A–Z'},{value:'category',label:'By category'}],data.order||'new')}</label>`);break;
case 'apply-order':data.order=overlay.querySelector('[name=order]').value;save();if(data.order==='new')data.items.sort((a,b)=>b.createdAt-a.createdAt);else data.items.sort((a,b)=>a[data.order].localeCompare(b[data.order]));slide=0;closeModal();render();break;
case 'item-options':{const i=picked();modal(i.name,`<div class="action-list">${btn('Add to collection','choose-collection','settings-row','layers')}${btn(i.modelKey?'Replace 3D model':'Attach a 3D model','attach-model','settings-row','cube')}${btn('Remove piece','remove-item','settings-row danger','trash')}</div>`);break}
case 'edit-item':editingItem=true;closeModal();render({instant:true});break;
case 'cancel-edit':editingItem=false;render({instant:true});break;
case 'attach-model':modal('A new dimension.',`<p>Attach a self-contained .glb model of this garment.</p><label class="dropzone" for="attach-file" style="margin-top:18px">${icon('cube')}<h3>Choose a 3D model</h3><p>GLB 2.0 · Up to 50 MB</p></label><input class="file-input" type="file" id="attach-file" accept=".glb">`);break;
case 'remove-item':modal('Remove this piece?',`<p>It will also be removed from outfits, collections, and packing lists.</p>${btn('Remove piece','confirm-remove-item','primary danger')}`);break;
case 'confirm-remove-item':{const i=picked();for(const k of [i.photoKey,i.modelKey,i.sourceKey,i.renderKey])if(k){await delBlob(k);URL.revokeObjectURL(urls.get(k));urls.delete(k)}data.items=data.items.filter(x=>x.id!==i.id);data.favorites=data.favorites.filter(id=>id!==i.id);for(const x of [...data.outfits,...data.collections,...data.trips]){x.itemIds=x.itemIds.filter(id=>id!==i.id);if(x.packed)x.packed=x.packed.filter(id=>id!==i.id)}save();slide=0;go('closet');toast('Piece removed.');break}
case 'new-collection':modal('A little collection.',`<form id="collection-form"><label class="field">Name<input name="name" required maxlength="70" placeholder="Give your collection a name"></label><button class="primary">Create collection ${icon('plus')}</button></form>`);break;
case 'all-collections':selectedCollection='';render();break;
case 'collection-pieces':choosePieces('collection-pieces-form',data.collections.find(c=>c.id===selectedCollection)?.itemIds||[]);break;
case 'collection-options':selectedCollection=el.dataset.id;modal('Collection options.',`<div class="action-list">${btn('Choose pieces','collection-pieces','settings-row','layers')}${btn('Rename collection','rename-collection','settings-row','edit')}${btn('Remove collection','delete-collection','settings-row danger','trash')}</div>`);break;
case 'rename-collection':modal('A new name.',`<form id="rename-collection-form"><label class="field">Name<input name="name" required maxlength="70" value="${esc(data.collections.find(c=>c.id===selectedCollection).name)}"></label><button class="primary">Save name</button></form>`);break;
case 'delete-collection':data.collections=data.collections.filter(c=>c.id!==selectedCollection);selectedCollection='';save();closeModal();render();toast('Collection removed. Your pieces are still in your closet.');break;
case 'choose-collection':if(!data.collections.length){modal('A place for your piece.',`<p>Create a collection first, then add your garment.</p>${btn('Create a collection','new-collection','primary','layers')}`);break}modal('Add to a collection.',data.collections.map(c=>btn(esc(c.name),'put-collection','settings-row','layers',`data-id="${c.id}"`)).join(''));break;
case 'put-collection':{const c=data.collections.find(c=>c.id===el.dataset.id);c.itemIds=[...new Set([...c.itemIds,picked().id])];save();closeModal();toast('Added to '+c.name+'.');break}
case 'new-outfit':selectedOutfit='';choosePieces('outfit-form');break;
case 'edit-outfit':selectedOutfit=el.dataset.id||selectedOutfit;choosePieces('outfit-form',byOutfit(selectedOutfit)?.itemIds||[],'Your look.');break;
case 'outfit-options':selectedOutfit=el.dataset.id;modal(byOutfit(selectedOutfit).name,`<div class="action-list">${btn('Edit outfit','edit-outfit','settings-row','edit')}${btn('Remove outfit','delete-outfit','settings-row danger','trash')}</div>`);break;
case 'delete-outfit':data.outfits=data.outfits.filter(o=>o.id!==selectedOutfit);data.plans=data.plans.filter(p=>p.outfitId!==selectedOutfit);save();go('outfits');toast('Outfit removed. Your pieces are still in your closet.');break;
case 'plan':planModal();break;
case 'delete-plan':data.plans=data.plans.filter(p=>p.id!==el.dataset.id);save();render();break;
case 'prev-week':activeDay.setDate(activeDay.getDate()-7);render();break;
case 'next-week':activeDay.setDate(activeDay.getDate()+7);render();break;
case 'planner-date':modal('Choose a day.',`<form id="planner-date-form">${datePicker('date',dateKey(activeDay))}<button class="primary">View day ${icon('arrow')}</button></form>`);break;
case 'new-trip':tripForm();break;
case 'edit-trip':tripForm(true);break;
case 'switch-trip':selectedTrip=el.dataset.id;render();break;
case 'trip-pieces':choosePieces('trip-pieces-form',data.trips.find(t=>t.id===selectedTrip)?.itemIds||[]);break;
case 'trip-options':modal('Trip options.',`<div class="action-list">${btn('Edit trip','edit-trip','settings-row','edit')}${btn('Remove trip','delete-trip','settings-row danger','trash')}</div>`);break;
case 'delete-trip':data.trips=data.trips.filter(t=>t.id!==selectedTrip);selectedTrip='';save();closeModal();render();break;
case 'edit-profile':modal('A little more you.',`<form id="profile-form"><label class="field">Name<input name="name" maxlength="70" value="${esc(data.profile.name)}" placeholder="Your name"></label><label class="field">Email<input name="email" type="email" value="${esc(data.profile.email)}" placeholder="Optional"></label><button class="primary">Save profile ${icon('check')}</button></form>`);break;
case 'styles':modal('Feels like you.',`<form id="styles-form"><div class="style-choices">${['Casual','Minimal','Classic','Streetwear','Formal','Sporty'].map(s=>`<label><input type="checkbox" name="style" value="${s}" ${data.styles.includes(s)?'checked':''}><span>${s}${icon('check')}</span></label>`).join('')}</div><button class="primary">Save preferences ${icon('check')}</button></form>`);break;
case 'body':modal('Your sizing notes.',`<form id="body-form"><div class="form-pair"><label class="field">Height (cm)<input name="height" type="number" min="50" max="250" value="${esc(data.body.height||'')}" placeholder="Optional"></label><label class="field">Size${select('size',['XS','S','M','L','XL','XXL'],data.body.size||'','Choose size')}</label></div><label class="field">Fit${select('fit',['Relaxed','Regular','Fitted'],data.body.fit||'','Choose fit')}</label><button class="primary">Save notes ${icon('check')}</button></form>`);break;
case 'backup':modal('Keep a little copy.',`<p>Your wardrobe stays in this browser. Export a backup to take your photos, models, and plans with you.</p>${btn('Export wardrobe','export-data','primary','download')}<label class="secondary restore-label" for="restore-file">${icon('upload')} Restore a backup</label><input id="restore-file" class="file-input" type="file" accept="application/json">`);break;
case 'export-data':await exportData();break;
case 'help':modal('Make yourself at home.',`<div class="help-points"><div>${icon('closet')}<p>Add a garment photo. Touch and drag it to explore a little depth.</p></div><div>${icon('outfits')}<p>Bring pieces together into looks, collections, and plans.</p></div><div>${icon('camera')}<p>Open Try-On from the dock’s Add menu. Lucy dresses your live camera view.</p></div></div>`);break;
case 'open-camera':go('tryon');break;
case 'start-camera':await startLucy();break;
case 'exit-camera':go('home');break;
case 'stop-lucy':stopCamera();render();break;
case 'capture':await capture();break;
}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const position=e.target.selectionStart;query=e.target.value;slide=0;refreshCloset();const input=document.querySelector('#search');input.focus();input.setSelectionRange(position,position)}});
document.addEventListener('change',async e=>{if(['garment-file','camera-file'].includes(e.target.id))await ingestPhoto(e.target.files[0]);if(e.target.id==='attach-file')await prepareUpload(e.target.files[0],true);if(e.target.id==='restore-file')await restore(e.target.files[0])});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,f=new FormData(form),v=Object.fromEntries(f);switch(form.id){case 'unlock-form':{const r=await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:v.password})});if(!r.ok){toast('That password did not match.');return}closeModal();const fn=unlockCallback;unlockCallback=null;fn?.();break}case 'upload-form':{if(!uploadDraft)return;const b=form.querySelector('[type=submit]');b.disabled=true;try{const key=uid();await storeBlob(key,uploadDraft.blob);const i={id:uid(),name:v.name.trim(),category:v.category,color:v.color.trim(),brand:v.brand.trim(),notes:'',price:0,createdAt:Date.now(),[uploadDraft.isModel?'modelKey':'photoKey']:key};urls.set(key,uploadDraft.url);data.items.unshift(i);if(!save()){data.items.shift();await delBlob(key);break}selected=i.id;slide=0;uploadDraft=null;go('closet');toast('A new piece, right at home.')}catch{toast('This piece could not be saved. Try freeing some device storage.')}finally{b.disabled=false}break}case 'item-form':Object.assign(picked(),{...v,name:v.name.trim(),price:Number(v.price??picked().price??0)});save();editingItem=false;closeModal();render({instant:true});break;case 'outfit-form':{const ids=f.getAll('items');if(!ids.length){toast('Choose at least one piece.');return}const existing=byOutfit(selectedOutfit);if(existing){existing.name=v.name.trim();existing.itemIds=ids}else{const o={id:uid(),name:v.name.trim(),itemIds:ids};data.outfits.push(o);selectedOutfit=o.id}save();go('look');toast('Your look is saved.');break}case 'collection-form':data.collections.push({id:uid(),name:v.name.trim(),itemIds:[]});save();go('collections');break;case 'rename-collection-form':data.collections.find(c=>c.id===selectedCollection).name=v.name.trim();save();closeModal();render();break;case 'collection-pieces-form':data.collections.find(c=>c.id===selectedCollection).itemIds=f.getAll('items');save();closeModal();render();break;case 'plan-form':if(!v.date||!byOutfit(v.outfitId)){toast('Choose an outfit and a date.');return}data.plans.push({...v,id:uid()});save();activeDay=new Date(v.date+'T12:00:00');go('planner');toast('A look to look forward to.');break;case 'planner-date-form':if(v.date){activeDay=new Date(v.date+'T12:00:00');closeModal();render()}break;case 'trip-form':if(!v.start||!v.end||v.end<v.start){toast('Choose a return date on or after departure.');return}if(form.dataset.edit)Object.assign(data.trips.find(t=>t.id===form.dataset.edit),v);else{const t={...v,id:uid(),itemIds:[],packed:[]};data.trips.push(t);selectedTrip=t.id}save();go('packing');break;case 'trip-pieces-form':{const t=data.trips.find(t=>t.id===selectedTrip);t.itemIds=f.getAll('items');t.packed=t.packed.filter(id=>t.itemIds.includes(id));save();closeModal();render();break}case 'profile-form':data.profile={name:v.name.trim(),email:v.email.trim()};save();closeModal();render();break;case 'styles-form':data.styles=f.getAll('style');save();closeModal();render();break;case 'body-form':data.body=v;save();closeModal();render();break}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const open=document.querySelector('.select-options:not([hidden]),.date-options:not([hidden])');if(open)closeDropdowns();else closeModal()}if(e.key==='Tab'&&overlay.firstChild){const nodes=[...overlay.querySelectorAll('button,a,input:not([type=hidden]):not([type=file]),textarea')].filter(x=>!x.disabled&&x.getClientRects().length);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0]?.focus()}}if(e.target.closest('.select-options')&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const list=[...e.target.closest('.select-options').querySelectorAll('button')],n=list.indexOf(e.target);list[(n+(e.key==='ArrowDown'?1:-1)+list.length)%list.length].focus()}if(!overlay.firstChild&&!e.target.matches('input,textarea,button')&&['closet','viewer'].includes(page)){if(e.key==='ArrowLeft')moveSlide(-1);if(e.key==='ArrowRight')moveSlide(1)}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1)||'home';if(p!==page)go(p)});window.addEventListener('pagehide',()=>{stopCamera();stopTilt?.()});

function lucyView(){const photos=data.items.filter(i=>photo(i));if(!cameraItem&&photos.length)cameraItem=photos[0].id;const live=lucyStatus==='live';return heading('The Fitting Room.','A new look. Still you.',round('close','exit-camera','Leave fitting room'))+`<div class="camera-layout"><div class="camera-stage ${live?'':'camera-off'}">${remoteStream||stream?'<video id="camera-video" autoplay muted playsinline></video>':`<div class="empty-state"><div class="pulse-orb ${lucyConnecting?'loading-orb':''}">${icon('camera')}</div><h2>${lucyConnecting?'A moment, just for you.':'See it on you.'}</h2><p>${lucyConnecting?'Connecting to Lucy…':'Choose a piece. Let Lucy bring your look to life.'}</p></div>`}${stream?`<div class="camera-controls"><span class="camera-label">${live?'LUCY · LIVE':'CONNECTING'}</span>${round('close','stop-lucy','End Try-On')}</div>`:''}${remoteStream?'<button class="shutter" data-action="capture" aria-label="Capture your look"></button>':''}</div><aside class="adjust-panel glass"><div class="lucy-status ${live?'live':''}"><i></i>${live?'Connected':lucyConnecting?'Connecting':'Your live wardrobe'}</div><h2 class="lucy-title">Try a little<br>something different.</h2><p class="lucy-byline">POWERED BY LUCY</p>${photos.length?`<div class="camera-pieces">${photos.map(i=>`<button class="${i.id===cameraItem?'active':''}" data-camera-item="${i.id}" aria-label="Try ${esc(i.name)}" aria-pressed="${i.id===cameraItem}">${thumb(i)}</button>`).join('')}</div><p class="small muted" style="margin-top:13px">${esc(itemBy(cameraItem)?.name||'Choose a garment')}</p>`:'<p class="asset-note">Add a garment photo to get started.</p>'}${!lucySession?btn(lucyConnecting?'Connecting…':'Start Try-On','start-camera','primary lucy-start','camera',!photos.length||lucyConnecting?'disabled':''):''}${!lucySession?'<p class="lucy-disclosure">Starting Try-On sends your camera and chosen garment to Decart for live processing.</p>':''}</aside></div>`}
views.tryon=lucyView;views.permission=lucyView;


const processingIds=new Set();
function slideDots(){return `<div class="stage-navigation"><div class="slide-dots" aria-label="Garment slides">${filtered().map((x,n)=>`<button data-slide="${n}" class="slide-dot ${x.id===selected?'active':''}" aria-label="View ${esc(x.name)}" aria-current="${x.id===selected?'true':'false'}"></button>`).join('')}</div></div>`}
function pendingStage(i){const active=i.status==='processing';return `<div class="garment-stage glass"><div class="stage-aura"></div><div class="empty-state">${scene("closet")}<h2>${active?'Finding its shape.':i.status==='failed'?'A little more time.':'Your piece is saved.'}</h2><p>${active?'Recognizing your garment and creating its render.':i.status==='failed'?'Processing was interrupted. Your original photo is safe.':'Waiting for garment processing to connect.'}</p>${i.status==='failed'?btn('Try again','retry-render','secondary','rotate'):''}</div>${slideDots()}</div>`}
async function ingestPhoto(file){if(!file)return;try{if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>15*1024*1024)throw Error('Choose a JPG, PNG or WebP under 15 MB.');const image=await createImageBitmap(file),r=Math.min(1,1200/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*r);canvas.height=Math.round(image.height*r);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.88));if(!blob)throw Error('This photo could not be opened.');const sourceKey=uid();await storeBlob(sourceKey,blob);urls.set(sourceKey,URL.createObjectURL(blob));const i={id:uid(),name:'New piece',category:'Other',color:'',brand:'',notes:'',createdAt:Date.now(),sourceKey,status:'waiting'};data.items.unshift(i);if(!save()){data.items.shift();await delBlob(sourceKey);throw Error('Your device could not save the photo.')}selected=i.id;slide=0;go('closet');startRender(i)}catch(err){toast(err.message||'This photo could not be saved.')}}
async function startRender(i){if(processingIds.has(i.id)||!i.sourceKey)return;processingIds.add(i.id);try{const status=await fetch('/api/garments/status').then(r=>r.json());if(!status.ready){i.status='waiting';save();return}if(status.locked){processingIds.delete(i.id);unlockModal(()=>startRender(i));return}i.status='processing';save();if(['closet','viewer'].includes(page)&&!overlay.firstChild)render({instant:true});const original=await getBlob(i.sourceKey),form=new FormData();form.append('image',original,'garment.webp');const response=await fetch('/api/garments/render',{method:'POST',body:form,signal:AbortSignal.timeout(175000)});if(!response.ok){const error=await response.json().catch(()=>({}));if(error.code==='LOCKED'){i.status='waiting';processingIds.delete(i.id);unlockModal(()=>startRender(i));return}if(error.code==='NOT_CONFIGURED'){i.status='waiting';save();return}throw Error(error.error||'Garment processing could not complete.')}const metadata=JSON.parse(decodeURIComponent(response.headers.get('X-Garment-Metadata')||'%7B%7D')),rendered=await cleanRender(await response.blob()),key=uid();await storeBlob(key,rendered);if(!data.items.some(x=>x.id===i.id)){await delBlob(key);return}urls.set(key,URL.createObjectURL(rendered));Object.assign(i,{renderKey:key,name:typeof metadata.name==='string'?metadata.name:'Your garment',category:cats.includes(metadata.category)?metadata.category:'Other',color:typeof metadata.color==='string'?metadata.color:'',status:'ready'});save();if(['closet','viewer'].includes(page)&&!overlay.firstChild)render({instant:true});toast('Your garment is ready.')}catch(err){if(data.items.some(x=>x.id===i.id)){i.status='failed';save();if(['closet','viewer'].includes(page)&&!overlay.firstChild)render({instant:true});toast(err.message||'Your photo is saved. Processing can be retried.')}}finally{processingIds.delete(i.id)}}
async function cleanRender(blob){const image=await createImageBitmap(blob),c=document.createElement('canvas');c.width=image.width;c.height=image.height;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);image.close();const pixels=ctx.getImageData(0,0,c.width,c.height),a=pixels.data,w=c.width,h=c.height,visited=new Uint8Array(w*h),queue=new Int32Array(w*h);let head=0,tail=0;const add=n=>{if(n<0||n>=w*h||visited[n])return;visited[n]=1;const x=n*4;if(a[x]>247&&a[x+1]>247&&a[x+2]>247){queue[tail++]=n;a[x+3]=0}};for(let x=0;x<w;x++){add(x);add((h-1)*w+x)}for(let y=0;y<h;y++){add(y*w);add(y*w+w-1)}while(head<tail){const n=queue[head++];if(n%w)add(n-1);if(n%w<w-1)add(n+1);add(n-w);add(n+w)}ctx.putImageData(pixels,0,0);return new Promise(resolve=>c.toBlob(resolve,'image/webp',.93))}
let unlockCallback=null;
function unlockModal(after){unlockCallback=after;modal('Your private wardrobe.',`<form id="unlock-form"><label class="field">Password<input name="password" type="password" autocomplete="current-password" required placeholder="Your wardrobe password"></label><button class="primary">Unlock ${icon('lock')}</button></form>`)}
async function resumeProcessing(){const pending=data.items.filter(i=>i.sourceKey&&!i.renderKey);for(const i of pending)await startRender(i)}

