function scene(kind='closet'){const id='s'+sceneSerial++;let drawing=kind==='bag'?'<path d="M51 54h78v88H51z"/><path d="M79 54V39h24v15M66 73v48m49-48v48M68 144v4m44-4v4"/>':kind==='calendar'?'<path d="M43 50h94v88H43zM43 74h94M65 40v22m50-22v22"/><path class="scene-line" d="m67 105 15 14 30-31"/>':kind==='outfits'?'<path d="m63 52 27 10 27-10 28 22-17 24-13-8v51H65V90l-13 8-17-24 28-22Z"/><path d="M75 56q15 20 30 0M78 121h24"/>':kind==='chart'?'<path d="M48 133V93h17v40M81 133V64h17v69m16 0V43h17v90"/>':'<path d="M80 42a10 10 0 1 1 14 9v13l49 39a9 9 0 0 1-5 17H42a9 9 0 0 1-5-17l53-40"/><path d="M90 70v67M57 94v40h66V94"/>';return `<svg class="scene scene-${kind}" viewBox="0 0 180 170" aria-hidden="true"><defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff" stop-opacity=".95"/><stop offset=".45" stop-color="#d7e5fb" stop-opacity=".6"/><stop offset="1" stop-color="#fff" stop-opacity=".9"/></linearGradient><filter id="${id}b"><feGaussianBlur stdDeviation="8"/></filter></defs><ellipse cx="90" cy="148" rx="49" ry="9" fill="#8ca9d5" opacity=".18" filter="url(#${id}b)"/><ellipse class="scene-orbit" cx="90" cy="86" rx="71" ry="57" fill="none" stroke="white" opacity=".7"/><g class="scene-object" fill="url(#${id})" stroke="#96b4e1" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${drawing}</g><circle class="scene-spark" cx="139" cy="45" r="3" fill="white"/><circle cx="38" cy="125" r="2" fill="#bfd0e9"/></svg>`}
function weatherKind(code){if(code>=95)return 'storm';if([71,73,75,77,85,86].includes(code))return 'snow';if(code>=51)return 'rain';if(code===45||code===48)return 'fog';if(code>0)return 'cloud';return 'sun'}
function weatherLabel(code){return({sun:'Clear skies',cloud:code===3?'Overcast':'Partly cloudy',rain:'Rain',snow:'Snow',storm:'Thunderstorms',fog:'Foggy'})[weatherKind(code)]}
function weatherGraphic(code=1,night=false,small=false){const k=weatherKind(code),id='w'+sceneSerial++;return `<svg class="weather-art ${k} ${small?'weather-art-small':''}" viewBox="0 0 200 160" aria-hidden="true"><defs><radialGradient id="${id}s"><stop stop-color="#fff2c9"/><stop offset=".65" stop-color="#f0d39d"/><stop offset="1" stop-color="#d9ba89" stop-opacity=".5"/></radialGradient><linearGradient id="${id}c" x1="0" y1="0" x2=".6" y2="1"><stop stop-color="#fff"/><stop offset="1" stop-color="#d9e7fa" stop-opacity=".9"/></linearGradient><filter id="${id}b"><feGaussianBlur stdDeviation="8"/></filter></defs><ellipse cx="102" cy="138" rx="51" ry="9" fill="#779acf" opacity=".16" filter="url(#${id}b)"/><g class="weather-sun">${night?`<path d="M110 28a34 34 0 1 0 32 47 30 30 0 0 1-32-47" fill="#e4ecff" stroke="white"/>`:`<circle cx="106" cy="61" r="34" fill="url(#${id}s)"/><circle cx="106" cy="61" r="43" fill="none" stroke="#eedec3" opacity=".35"/><g stroke="#e4cca6" stroke-width="1.5" stroke-linecap="round"><path d="M106 10v-4m0 110v-4M55 61h-4m110 0h-4M70 25l-3-3m78 78-3-3M70 97l-3 3m78-78-3 3"/></g>`}</g>${k!=='sun'?`<g class="weather-cloud"><path d="M52 113a22 22 0 0 1-1-44 30 30 0 0 1 56-8 25 25 0 0 1 34 27 17 17 0 0 1-3 34H52Z" fill="url(#${id}c)" stroke="white" stroke-width="1.5"/><path d="M55 115h75" stroke="#b8cfe9" stroke-opacity=".45" fill="none"/></g>`:''}${k==='rain'||k==='storm'?'<g class="weather-rain" stroke="#8aafdd" stroke-width="2" stroke-linecap="round"><path d="m68 128-4 8m24-4-4 8m25-12-4 8m23-4-4 8"/></g>':''}${k==='snow'?'<g class="weather-rain" fill="#bdd0eb"><circle cx="71" cy="135" r="3"/><circle cx="98" cy="141" r="2"/><circle cx="124" cy="133" r="3"/></g>':''}${k==='storm'?'<path d="m102 107-14 20h11l-3 18 20-25h-13l4-13" fill="#e6c68e" stroke="white"/>':''}${k==='fog'?'<g stroke="#bdcfe7" stroke-width="3" stroke-linecap="round"><path d="M58 130h80m-69 10h55"/></g>':''}</svg>`}
function weatherMini(){const w=data.weatherSnapshot,loc=data.weatherLocation;return `<button class="weather-mini glass" data-page="weather"><div>${weatherGraphic(w?.current?.weather_code??1,w?.current?.is_day===0,true)}</div><section><span class="eyebrow">${loc?esc(loc.name.split(',')[0]):'A LITTLE OUTSIDE IN'}</span><strong>${w?.current?Math.round(w.current.temperature_2m)+'°':'Your local weather'}</strong><p>${w?.current?weatherLabel(w.current.weather_code):'Dress for your day.'}</p></section>${icon('chevron')}</button>`}
function weatherView(){const w=data.weatherSnapshot,loc=data.weatherLocation,unit=w?(w.current_units?.temperature_2m==='°F'?'fahrenheit':'celsius'):(data.weatherUnit||'celsius');if(!w||!loc)return heading('Weather','A little outside inspiration.')+`<div class="weather-welcome glass"><div class="weather-welcome-art">${weatherGraphic(1)}</div><h2>Dress for your day.</h2><div class="weather-connect">${btn(weatherLoading?'Finding your forecast…':'Use my location','weather-locate','primary','location',weatherLoading?'disabled':'')}${btn('Choose a city','weather-city','text-btn')}</div>${weatherError?`<p class="weather-error">${esc(weatherError)}</p>`:''}<a class="weather-attribution" href="https://open-meteo.com/" target="_blank" rel="noopener">Forecasts by Open-Meteo</a></div>`;const c=w.current,d=w.daily,h=w.hourly,from=c.time.slice(0,13)+':00',hours=h.time.map((t,n)=>({t,n})).filter(x=>x.t>=from).slice(0,12),lo=Math.min(...d.temperature_2m_min),hi=Math.max(...d.temperature_2m_max),range=Math.max(1,hi-lo),temp=c.temperature_2m,advice=c.precipitation>0?'Rain, meet your outerwear.':(unit==='fahrenheit'?temp<50:temp<10)?'A little extra warmth.':(unit==='fahrenheit'?temp>77:temp>25)?'Keep it light.':'A day for light layers.';return heading('Weather',loc.name,round('location','weather-city','Choose a city'))+`<div class="weather-dashboard"><section class="forecast-hero glass"><div class="forecast-now"><div><p class="eyebrow">RIGHT HERE, RIGHT NOW</p><strong>${Math.round(c.temperature_2m)}<sup>°</sup></strong><h2>${weatherLabel(c.weather_code)}</h2><p>H ${Math.round(d.temperature_2m_max[0])}° <span>L ${Math.round(d.temperature_2m_min[0])}°</span></p></div>${weatherGraphic(c.weather_code,c.is_day===0)}</div><div class="weather-unit" role="group" aria-label="Temperature units">${btn('°C','weather-celsius','pill '+(unit==='celsius'?'active':''))}${btn('°F','weather-fahrenheit','pill '+(unit==='fahrenheit'?'active':''))}</div></section><section class="weather-outfit glass">${scene(c.precipitation>0?'bag':'outfits')}<h2>${advice}</h2>${btn('Explore your closet','closet','text-btn','arrow')}</section></div><section class="hourly glass"><div class="section-head"><h2>The hours ahead.</h2><span>${icon('sun')}</span></div><div class="hourly-strip">${hours.map(({t,n},i)=>`<div class="hourly-item"><span>${i===0?'Now':t.slice(11,16)}</span>${weatherGraphic(i===0?c.weather_code:h.weather_code[n],i===0?c.is_day===0:((h.is_day?.[n]??(t<d.sunrise[d.time.indexOf(t.slice(0,10))]||t>=d.sunset[d.time.indexOf(t.slice(0,10))]?0:1))===0),true)}<strong>${Math.round(i===0?c.temperature_2m:h.temperature_2m[n])}°</strong>${h.precipitation_probability[n]>0?`<small>${h.precipitation_probability[n]}%</small>`:'<small></small>'}</div>`).join('')}</div></section><div class="weather-bottom"><section class="daily glass"><h2>The week, softly planned.</h2>${d.time.map((date,n)=>`<div class="day-forecast"><strong>${n===0?'Today':new Date(date+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'})}</strong>${weatherGraphic(d.weather_code[n],false,true)}<span>${Math.round(d.temperature_2m_min[n])}°</span><div class="temperature-track"><i style="left:${(d.temperature_2m_min[n]-lo)/range*100}%;width:${Math.max(3,(d.temperature_2m_max[n]-d.temperature_2m_min[n])/range*100)}%"></i></div><span>${Math.round(d.temperature_2m_max[n])}°</span></div>`).join('')}</section><div class="weather-measures">${[['thermometer','Feels like',Math.round(c.apparent_temperature)+'°'],['wind','Wind',Math.round(c.wind_speed_10m)+' '+(unit==='fahrenheit'?'mph':'km/h')],['drop','Humidity',c.relative_humidity_2m+'%'],['sun','Sunset',d.sunset[0].slice(11,16)]].map(([ic,l,v])=>`<div class="weather-measure glass">${icon(ic)}<span>${l}</span><strong>${v}</strong></div>`).join('')}</div></div><p class="weather-footer">${weatherLoading?'Refreshing…':'Updated '+c.time.slice(11,16)} · ${esc(w.timezone)} · <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a></p>${weatherError?`<p class="weather-error">${esc(weatherError)} Showing the last saved forecast.</p>`:''}`}
function profileVisual(){const name=data.profile.name,letters=name?name.split(' ').map(x=>x[0]).slice(0,2).join(''):'';return heading('Profile','',round('grid','navigation','Explore your wardrobe'))+`<div class="profile-visual"><section class="profile-hero glass"><div class="profile-light"></div>${round('edit','edit-profile','Edit your profile')}<div class="profile-orbit"><span></span><span></span><div class="profile-emblem">${letters?`<strong>${esc(letters)}</strong>`:icon('closet')}</div><i>${icon('sparkle')}</i></div><h2>${esc(name||'Entirely you.')}</h2><p>${esc(data.profile.email||'A little space for your style.')}</p><div class="profile-numbers"><button data-page="closet"><strong>${data.items.length}</strong><span>${data.items.length===1?'Piece':'Pieces'}</span></button><button data-page="outfits"><strong>${data.outfits.length}</strong><span>${data.outfits.length===1?'Look':'Looks'}</span></button><button data-page="collections"><strong>${data.collections.length}</strong><span>${data.collections.length===1?'Collection':'Collections'}</span></button></div></section>${weatherMini()}<div class="profile-tile-grid">${[['sparkle','Your style',data.styles.length?data.styles.slice(0,2).join(' · '):'Make it yours','styles'],['profile','Your fit',data.body.size||'Sizing notes','body'],['cloud','Keep a copy','Your wardrobe, with you','backup'],['help','A little guidance','Make yourself at home','help']].map(([ic,t,s,a])=>`<button class="profile-tile glass" data-action="${a}"><div class="tile-art">${icon(ic)}<i></i></div><h3>${t}</h3><p>${esc(s)}</p>${icon('chevron')}</button>`).join('')}</div><p class="profile-device">${icon('lock')} Saved on this device</p></div>`}
function weatherSearch(){modal('A little closer to you.',`<form id="weather-city-form" class="weather-search"><label class="search">${icon('search')}<input name="city" aria-label="City name" placeholder="Find your city…" required minlength="2" autocomplete="off"><button class="round" type="submit" aria-label="Find city">${icon('arrow')}</button></label></form><div id="weather-city-results" class="weather-city-results"></div>`)}
async function searchCities(value){const results=overlay.querySelector('#weather-city-results');results.innerHTML='<div class="city-loading">'+weatherGraphic(1,false,true)+'</div>';try{const r=await fetch('https://geocoding-api.open-meteo.com/v1/search?'+new URLSearchParams({name:value,count:'6',language:'en',format:'json'}),{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();weatherChoices=(await r.json()).results||[];results.innerHTML=weatherChoices.length?weatherChoices.map((c,n)=>`<button class="city-result" data-weather-city="${n}">${icon('location')}<div><strong>${esc(c.name)}</strong><span>${esc([c.admin1,c.country].filter(Boolean).join(', '))}</span></div>${icon('chevron')}</button>`).join(''):'<p class="small muted" style="text-align:center;padding:20px">No city found. Try a nearby place.</p>'}catch{results.innerHTML='<p class="small muted" style="padding:20px;text-align:center">The city search could not connect. Try again.</p>'}}
async function useLocation(){if(!navigator.geolocation){weatherSearch();return}weatherLoading=true;weatherError='';render();navigator.geolocation.getCurrentPosition(async p=>{data.weatherSnapshot=null;data.weatherLocation={name:'Near you',latitude:Math.round(p.coords.latitude*100)/100,longitude:Math.round(p.coords.longitude*100)/100};save();await loadWeather()},()=>{weatherLoading=false;weatherError='Choose a city to see your forecast.';render();weatherSearch()},{enableHighAccuracy:false,timeout:12000,maximumAge:1800000})}
async function loadWeather(){const loc=data.weatherLocation;if(!loc)return;weatherLoading=true;weatherError='';if(page==='weather')render();try{const unit=data.weatherUnit||'celsius',params=new URLSearchParams({latitude:String(loc.latitude),longitude:String(loc.longitude),current:'temperature_2m,apparent_temperature,relative_humidity_2m,is_day,precipitation,weather_code,wind_speed_10m',hourly:'temperature_2m,weather_code,precipitation_probability,is_day',daily:'weather_code,temperature_2m_max,temperature_2m_min,sunrise,sunset',timezone:'auto',forecast_days:'7',temperature_unit:unit,wind_speed_unit:unit==='fahrenheit'?'mph':'kmh'}),r=await fetch('https://api.open-meteo.com/v1/forecast?'+params,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();const result=await r.json();if(!result.current||!result.hourly||!result.daily)throw Error();data.weatherSnapshot=result;data.weatherFetchedAt=Date.now();save()}catch{weatherError='The weather could not refresh.'}finally{weatherLoading=false;if(['weather','profile','home'].includes(page)&&!overlay.firstChild)render()}}
navs.push(['weather','sun','Weather']);titles.weather='Weather';views.weather=weatherView;views.profile=profileVisual;
const originalHome=views.home;views.home=()=>originalHome()+weatherMini();
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.weatherCity!==undefined){const c=weatherChoices[Number(b.dataset.weatherCity)];if(!c)return;data.weatherLocation={name:[c.name,c.admin1].filter(Boolean).join(', '),latitude:c.latitude,longitude:c.longitude};data.weatherSnapshot=null;save();go('weather');await loadWeather();return}switch(b.dataset.action){case 'weather-city':weatherSearch();break;case 'weather-locate':await useLocation();break;case 'weather-celsius':case 'weather-fahrenheit':data.weatherUnit=b.dataset.action==='weather-celsius'?'celsius':'fahrenheit';save();await loadWeather();break}});
document.addEventListener('submit',async e=>{if(e.target.id==='weather-city-form'){e.preventDefault();await searchCities(new FormData(e.target).get('city').trim())}});


function refreshCloset(){if(!['closet','viewer'].includes(page)){render({instant:true});return}const old=document.querySelector('.garment-card');if(!old){render({instant:true});return}const template=document.createElement('div');template.innerHTML=closet(page==='viewer');const next=template.querySelector('.garment-card');old.replaceWith(next);document.querySelectorAll('[data-category]').forEach(el=>{const active=el.dataset.category===category;el.classList.toggle('active',active);el.setAttribute('aria-selected',active)});document.querySelector('[data-action="favorites-only"]')?.setAttribute('aria-pressed',onlyFavorites);next.querySelector('.slide-content')?.style.setProperty('animation','none');bindStage()}

async function boot(){try{db=await openDB();for(const i of data.items){if(i.photoKey&&!i.renderKey&&!i.modelKey){i.sourceKey=i.photoKey;delete i.photoKey;i.status='waiting'}if(i.status==='processing')i.status='waiting'}save();await preload();render();resumeProcessing();if(data.weatherLocation&&Date.now()-(data.weatherFetchedAt||0)>900000)loadWeather()}catch{app.innerHTML=shell(`<div class="glass">${empty('A little space is needed.','Enable browser storage to save and explore your wardrobe.','','','lock')}</div>`)}}
boot();
